    71	
    72	  address[0] = (uint8_t)(regaddr >> 8);
    73	  address[1] = (uint8_t)regaddr;
    74	
    75	  messages[0].frequency = SC2336_SCCB_FREQUENCY;
    76	  messages[0].addr = SC2336_SCCB_ADDRESS;
    77	  messages[0].flags = I2C_M_NOSTOP;
    78	  messages[0].buffer = address;
    79	  messages[0].length = sizeof(address);
    80	
    81	  messages[1].frequency = SC2336_SCCB_FREQUENCY;
    82	  messages[1].addr = SC2336_SCCB_ADDRESS;
    83	  messages[1].flags = I2C_M_READ;
    84	  messages[1].buffer = value;
    85	  messages[1].length = 1;
    86	
    87	  transfer.msgv = messages;
